 1	export class ApiError extends Error {
 2	  status: number
 3	  body: unknown
 4	
 5	  constructor(status: number, body: unknown) {
 6	    const message =
 7	      typeof body === 'object' && body !== null && 'error' in body && typeof (body as { error: unknown }).error === 'string'
 8	        ? (body as { error: string }).error
 9	        : `Request failed (${status})`
10	    super(message)
11	    this.status = status
12	    this.body = body
13	  }
14	}
15	
16	export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
17	  const res = await fetch(`/api${path}`, {
18	    ...init,
19	    credentials: 'include',
20	    headers: { 'Content-Type': 'application/json', ...init?.headers },
21	  })
22	  const body = await res.json().catch(() => undefined)
23	  if (!res.ok) throw new ApiError(res.status, body)
24	  return body as T
25	}
26	
27	/** Test-only helper: builds a real Response for stubbed fetch calls. */
28	export function mockJsonResponse(status: number, body: unknown): Response {
29	  return new Response(JSON.stringify(body), {
30	    status,
31	    headers: { 'Content-Type': 'application/json' },
32	  })
33	}

