 1	import { apiFetch } from '../lib/api.js'
 2	
 3	export interface NoteSummary {
 4	  id: string
 5	  path: string
 6	  type: string
 7	  name: string
 8	  frontmatter: Record<string, unknown>
 9	  updatedAt: string
10	}
11	
12	export type VaultTree = Record<string, NoteSummary[]>
13	
14	export function getVaultTree(vaultId: string): Promise<VaultTree> {
15	  return apiFetch(`/vaults/${vaultId}/tree`)
16	}
17	
18	export interface NoteDetail {
19	  path: string
20	  frontmatter: Record<string, unknown>
21	  body: string
22	  updatedAt: string
23	}
24	
25	export function getNote(vaultId: string, path: string): Promise<NoteDetail> {
26	  return apiFetch(`/vaults/${vaultId}/notes/${path}`)
27	}
28	
29	export interface UpdateNoteInput {
30	  frontmatter?: Record<string, unknown>
31	  body?: string
32	}
33	
34	export interface UpdateNoteResult {
35	  id: string
36	  path: string
37	  frontmatter: Record<string, unknown>
38	  body: string
39	  updatedAt: string
40	}
41	
42	export function updateNote(vaultId: string, path: string, input: UpdateNoteInput): Promise<UpdateNoteResult> {
43	  return apiFetch(`/vaults/${vaultId}/notes/${path}`, { method: 'PUT', body: JSON.stringify(input) })
44	}

